                <div>
                    <label for="dateMade">Date Made</label>
                    <input type="date" id="dateMade" required>
                </div>
                <div>
                    <label for="location">Location</label>
                    <select id="location">
                        <option value="Fridge - Top Shelf">Fridge - Top Shelf</option>
                        <option value="Fridge - Middle Shelf">Fridge - Middle Shelf</option>
                        <option value="Fridge - Bottom Shelf">Fridge - Bottom Shelf</option>
                        <option value="Fridge - Crisper">Fridge - Crisper</option>
                        <option value="Freezer">Freezer</option>
                    </select>
                </div>
                <div>
                    <label for="daysLast">Days It Lasts</label>
                    <input type="number" id="daysLast" value="4" min="1" required>
                </div>
            </div>
            <button type="submit">Add Item</button>
            <button type="button" class="btn-print" onclick="window.print()">Print Labels</button>
        </form>
    </div>

    <div class="card">
        <h2>⏳ Use First List</h2>
        <ul id="useFirstList"></ul>
    </div>

    <div class="card">
        <h2 class="no-print">🖨️ Printable Labels</h2>
        <div class="labels-grid" id="labelsContainer"></div>
    </div>
</div>

<script>
    document.getElementById('dateMade').valueAsDate = new Date();

    let items = [];

    function addLeftover(event) {
        event.preventDefault();

        const food = document.getElementById('food').value;
        const owner = document.getElementById('owner').value || 'Everyone';
        const dateMadeStr = document.getElementById('dateMade').value;
        const location = document.getElementById('location').value;
        const daysLast = parseInt(document.getElementById('daysLast').value);

        const dateMade = new Date(dateMadeStr + 'T00:00:00');
        const expirationDate = new Date(dateMade);
        expirationDate.setDate(dateMade.getDate() + daysLast);

        const item = {
            id: Date.now(),
            food,
            owner,
            dateMade: dateMade.toLocaleDateString(),
            expirationDate: expirationDate,
            expirationDateStr: expirationDate.toLocaleDateString(),
            location,
            daysRemaining: Math.ceil((expirationDate - new Date().setHours(0,0,0,0)) / (1000 * 60 * 60 * 24))
        };

        items.push(item);
        updateUI();
        document.getElementById('leftoverForm').reset();
        document.getElementById('dateMade').valueAsDate = new Date();
    }

    function deleteItem(id) {
        items = items.filter(item => item.id !== id);
        updateUI();
    }

    function updateUI() {
        const listContainer = document.getElementById('useFirstList');
        const labelsContainer = document.getElementById('labelsContainer');

        listContainer.textContent = '';
        labelsContainer.textContent = '';

        items.sort((a, b) => a.expirationDate - b.expirationDate);

        if (items.length === 0) {
            const emptyLi = document.createElement('li');
            emptyLi.textContent = 'No items tracked yet.';
            listContainer.appendChild(emptyLi);
            return;
        }

        items.forEach(item => {
            // Render list item safely using DOM properties
            const li = document.createElement('li');

            const statusText = item.daysRemaining < 0 
                ? `EXPIRED` 
                : item.daysRemaining === 0 
                    ? `Use TODAY` 
                    : `Expires in ${item.daysRemaining} days`;

            const foodStrong = document.createElement('strong');
            foodStrong.textContent = item.food;

            const metaText = document.createTextNode(` (${item.owner}) — Use by: ${item.expirationDateStr} | `);

            const locEm = document.createElement('em');
            locEm.textContent = item.location;

            const statusTextNode = document.createTextNode(` [${statusText}]`);

            li.appendChild(foodStrong);
            li.appendChild(metaText);
            li.appendChild(locEm);
            li.appendChild(statusTextNode);
            listContainer.appendChild(li);

            // Render label safely using DOM properties
            const labelCard = document.createElement('div');
            labelCard.className = 'label-card';

            const deleteBtn = document.createElement('button');
            deleteBtn.className = 'delete-btn no-print';
            deleteBtn.textContent = '×';
