            labelCard.appendChild(labelTitle);
            labelCard.appendChild(makeDetail('By:', item.owner));
            labelCard.appendChild(makeDetail('Made:', item.dateMade));
            labelCard.appendChild(makeDetail('USE BY:', item.expirationDateStr));
            labelCard.appendChild(makeDetail('Loc:', item.location));

            labelsContainer.appendChild(labelCard);
        });
